content:
[Write file: app.js]
/* ==========================================================================
   app.js — renders the pages from window.COURSE (see data.js)
   You should not need to edit this file to run your course.
   ========================================================================== */

(function () {
  "use strict";

  var C = window.COURSE;

  /* ---------- tiny helpers ---------------------------------------------- */

  function $(sel) { return document.querySelector(sel); }

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = text;
    return node;
  }

  // Set trusted HTML that comes from data.js (the instructor's own content).
  function html(node, markup) { node.innerHTML = markup; return node; }

  function fill(sel, value) {
    document.querySelectorAll(sel).forEach(function (n) { n.textContent = value; });
  }

  function isBlank(v) { return v === undefined || v === null || v === ""; }

  // "2027-01-19" -> "January 19, 2027". Anything else is passed through as-is.
  function prettyDate(iso) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || "").trim());
    if (!m) return iso || "";
    var months = ["January", "February", "March", "April", "May", "June", "July",
                  "August", "September", "October", "November", "December"];
    return months[Number(m[2]) - 1] + " " + Number(m[3]) + ", " + m[1];
  }

  /* ---------- shared chrome: title, nav, footer, contact ---------------- */

  function renderChrome() {
    document.title = C.code + " · " + C.title;

    fill("[data-course-code]", C.code);
    fill("[data-course-title]", C.title);
    fill("[data-course-term]", C.term);
    fill("[data-course-tagline]", C.tagline);
    fill("[data-instructor-name]", C.instructor.name);

    // Mark the current page in the nav (works without this too — see HTML).
    var page = document.body.getAttribute("data-page");
    document.querySelectorAll(".nav a").forEach(function (a) {
      if (a.getAttribute("data-nav") === page) {
        a.classList.add("is-current");
        a.setAttribute("aria-current", "page");
      }
    });

    var updated = $("[data-footer-updated]");
    if (updated) updated.textContent = C.footer.updated;
    var note = $("[data-footer-note]");
    if (note) note.textContent = C.footer.note;
    var year = $("[data-footer-year]");
    if (year) year.textContent = String(new Date().getFullYear());
  }

  /* ---------- contact block (appears on every page) --------------------- */

  function renderContact() {
    var host = $("[data-contact]");
    if (!host) return;

    var grid = el("div", "cards");

    // Instructor
    var card = el("div", "card");
    card.appendChild(el("h3", null, C.instructor.name));
    card.appendChild(el("p", "muted", "Instructor"));

    var dl = el("dl", "kv");
    addKV(dl, "Email", mailLink(C.instructor.email));
    if (!isBlank(C.instructor.office)) addKV(dl, "Office", document.createTextNode(C.instructor.office));
    if (!isBlank(C.instructor.officeHours)) addKV(dl, "Office hours", document.createTextNode(C.instructor.officeHours));
    card.appendChild(dl);

    if (!isBlank(C.instructor.note)) card.appendChild(el("p", "note", C.instructor.note));
    grid.appendChild(card);

    // Teaching assistants
    (C.assistants || []).forEach(function (ta) {
      var c = el("div", "card");
      c.appendChild(el("h3", null, ta.name));
      c.appendChild(el("p", "muted", "Teaching assistant"));
      var d = el("dl", "kv");
      addKV(d, "Email", mailLink(ta.email));
      if (!isBlank(ta.hours)) addKV(d, "Hours", document.createTextNode(ta.hours));
      c.appendChild(d);
      grid.appendChild(c);
    });

    host.appendChild(grid);

    // Where and when we meet
    var m = C.meetings;
    var meet = el("div", "card card--wide");
    meet.appendChild(el("h3", null, "When and where we meet"));
    var md = el("dl", "kv");
    addKV(md, "Lecture", document.createTextNode(m.lecture + " · " + m.lectureRoom));
    if (!isBlank(m.lab)) addKV(md, "Lab", document.createTextNode(m.lab + " · " + m.labRoom));
    meet.appendChild(md);
    host.appendChild(meet);

    var help = el("p", "note");
    help.appendChild(document.createTextNode("Emailing is always fine. I answer within one business day; " +
      "if two days pass with no reply, assume it got buried and send it again — I will not be annoyed."));
    host.appendChild(help);
  }

  function mailLink(address) {
    var a = el("a", null, address);
    a.href = "mailto:" + address;
    return a;
  }

  function addKV(dl, key, valueNode) {
    dl.appendChild(el("dt", null, key));
    var dd = el("dd");
    dd.appendChild(valueNode);
    dl.appendChild(dd);
  }

  /* ---------- code blocks with a Copy button ---------------------------- */

  var copyCounter = 0;

  function codeBlock(codeText, filename) {
    var wrap = el("div", "codeblock");

    var bar = el("div", "codeblock__bar");
    bar.appendChild(el("span", "codeblock__name", filename || "Python"));

    var btn = el("button", "copybtn", "Copy");
    btn.type = "button";
    var label = filename ? ("Copy " + filename + " to the clipboard")
                         : "Copy this code to the clipboard";
    btn.setAttribute("aria-label", label);
    bar.appendChild(btn);
    wrap.appendChild(bar);

    var pre = el("pre", "codeblock__pre");
    pre.setAttribute("tabindex", "0");                 // keyboard-scrollable
    var code = el("code", "language-python", codeText); // textContent — never innerHTML
    copyCounter += 1;
    code.id = "code-" + copyCounter;
    pre.appendChild(code);
    wrap.appendChild(pre);

    // A live region so screen readers hear the confirmation.
    var status = el("span", "sr-only");
    status.setAttribute("role", "status");
    wrap.appendChild(status);

    btn.addEventListener("click", function () {
      copyText(codeText, function (ok) {
        btn.textContent = ok ? "Copied" : "Press Ctrl+C";
        btn.classList.add(ok ? "is-copied" : "is-failed");
        status.textContent = ok ? "Code copied to clipboard."
                                : "Copy failed. The code is selected — press Control-C or Command-C.";
        if (!ok) selectNode(code);
        setTimeout(function () {
          btn.textContent = "Copy";
          btn.classList.remove("is-copied", "is-failed");
          status.textContent = "";
        }, 2500);
      });
    });

    return wrap;
  }

  // Clipboard API needs a secure context (https:// or localhost). Opening the
  // site as a file:// URL does not qualify, so fall back to execCommand, then
  // to simply selecting the text for the user.
  function copyText(text, done) {
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(
        function () { done(true); },
        function () { done(legacyCopy(text)); }
      );
      return;
    }
    done(legacyCopy(text));
  }

  function legacyCopy(text) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.top = "-1000px";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    var ok = false;
    try {
      ta.select();
      ok = document.execCommand("copy");
    } catch (e) {
      ok = false;
    }
    document.body.removeChild(ta);
    return ok;
  }

  function selectNode(node) {
    try {
      var range = document.createRange();
      range.selectNodeContents(node);
      var sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
    } catch (e) { /* selection is a nicety, not a requirement */ }
  }

  /* ---------- home page -------------------------------------------------- */

  function renderHome() {
    var host = $("[data-home]");
    if (!host) return;

    var desc = $("[data-course-description]");
    if (desc) desc.textContent = C.description;

    // Quick links
    var quick = $("[data-quicklinks]");
    if (quick) {
      var defs = [
        { key: "lms",      text: "Course LMS" },
        { key: "forum",    text: "Discussion forum" },
        { key: "gradebook", text: "Gradebook" }
      ];
      var any = false;
      defs.forEach(function (d) {
        var url = C.links[d.key];
        if (isBlank(url)) return;
        any = true;
        var a = el("a", "btn", d.text);
        a.href = url;
        a.rel = "noopener";
        quick.appendChild(a);
      });
      if (!any) quick.remove();
    }

    // "This week" panel
    var weekHost = $("[data-thisweek]");
    if (weekHost) {
      var wk = currentWeekEntry();
      if (!wk) {
        weekHost.appendChild(el("p", "muted",
          "The term has not started yet. The full plan is on the schedule page."));
      } else {
        var h = el("h3", null, wk.break ? wk.topic : ("Week " + wk.week + " — " + wk.topic));
        weekHost.appendChild(h);
        weekHost.appendChild(el("p", "muted", wk.dates));
        if ((wk.lecture || []).length) {
          weekHost.appendChild(bulletList(wk.lecture));
        }
        if (!isBlank(wk.due)) {
          var due = el("p", "pill pill--due");
          due.textContent = "Due this week: " + wk.due;
          weekHost.appendChild(due);
        }
        var more = el("a", "link", "See the full schedule →");
        more.href = "schedule.html";
        weekHost.appendChild(more);
      }
    }

    // Announcements
    var annHost = $("[data-announcements]");
    if (annHost) {
      var list = (C.announcements || []).slice(0, 5);
      if (!list.length) {
        annHost.appendChild(el("p", "muted", "No announcements yet."));
      } else {
        list.forEach(function (a) {
          var item = el("article", "announcement");
          item.appendChild(el("p", "announcement__date", prettyDate(a.date)));
          item.appendChild(el("h3", null, a.title));
          item.appendChild(html(el("div", "prose"), a.body));
          annHost.appendChild(item);
        });
      }
    }
  }

  function currentWeekEntry() {
    var n = Number(C.currentWeek);
    if (!n) return null;
    var found = null;
    (C.schedule || []).forEach(function (w) {
      if (!w.break && Number(w.week) === n) found = w;
    });
    return found;
  }

  function bulletList(items) {
    var ul = el("ul", "tight");
    items.forEach(function (t) { ul.appendChild(el("li", null, t)); });
    return ul;
  }

  /* ---------- syllabus --------------------------------------------------- */

  function renderSyllabus() {
    var host = $("[data-syllabus]");
    if (!host) return;

    // At-a-glance facts
    var facts = $("[data-syllabus-facts]");
    if (facts) {
      var dl = el("dl", "kv kv--split");
      addKV(dl, "Course", document.createTextNode(C.code + " · " + C.title));
      addKV(dl, "Term", document.createTextNode(C.term));
      addKV(dl, "Lecture", document.createTextNode(C.meetings.lecture + " · " + C.meetings.lectureRoom));
      if (!isBlank(C.meetings.lab)) {
        addKV(dl, "Lab", document.createTextNode(C.meetings.lab + " · " + C.meetings.labRoom));
      }
      addKV(dl, "Instructor", document.createTextNode(C.instructor.name));
      addKV(dl, "Email", mailLink(C.instructor.email));
      addKV(dl, "Office hours", document.createTextNode(C.instructor.officeHours));
      facts.appendChild(dl);
    }

    // Table of contents
    var toc = $("[data-syllabus-toc]");
    if (toc) {
      var ul = el("ul", "toc");
      (C.syllabusSections || []).forEach(function (s) {
        var li = el("li");
        var a = el("a", null, s.heading);
        a.href = "#" + s.id;
        li.appendChild(a);
        ul.appendChild(li);
      });
      var gradingLi = el("li");
      var ga = el("a", null, "Grading");
      ga.href = "#grading";
      gradingLi.appendChild(ga);
      ul.appendChild(gradingLi);
      toc.appendChild(ul);
    }

    // Prose sections
    var body = $("[data-syllabus-sections]");
    if (body) {
      (C.syllabusSections || []).forEach(function (s) {
        var sec = el("section", "section");
        sec.id = s.id;
        sec.appendChild(el("h2", null, s.heading));
        sec.appendChild(html(el("div", "prose"), s.body));
        body.appendChild(sec);
      });
    }

    // Grading table
    var gradeHost = $("[data-grading]");
    if (gradeHost) {
      var total = 0;
      (C.grading || []).forEach(function (g) { total += Number(g.weight) || 0; });

      var table = el("table", "table");
      var thead = el("thead");
      var hr = el("tr");
      ["Component", "Weight", "Notes"].forEach(function (h) {
        hr.appendChild(el("th", null, h));
      });
      thead.appendChild(hr);
      table.appendChild(thead);

      var tbody = el("tbody");
      (C.grading || []).forEach(function (g) {
        var tr = el("tr");
        tr.appendChild(withLabel(el("td", null, g.item), "Component"));
        tr.appendChild(withLabel(el("td", "num", g.weight + "%"), "Weight"));
        tr.appendChild(withLabel(el("td", "muted", g.notes || ""), "Notes"));
        tbody.appendChild(tr);
      });
      table.appendChild(tbody);

      var tfoot = el("tfoot");
      var fr = el("tr");
      fr.appendChild(el("td", null, "Total"));
      fr.appendChild(el("td", "num", total + "%"));
      fr.appendChild(el("td"));
      tfoot.appendChild(fr);
      table.appendChild(tfoot);

      gradeHost.appendChild(wrapTable(table));

      if (total !== 100) {
        var warn = el("p", "warning");
        warn.textContent = "Heads up (visible to everyone): the grading weights in data.js " +
          "add up to " + total + "%, not 100%. Fix the numbers in the 'grading' list.";
        gradeHost.appendChild(warn);
      }

      // Letter-grade scale
      if ((C.gradeScale || []).length) {
        gradeHost.appendChild(el("h3", null, "Letter grades"));
        var st = el("table", "table table--compact");
        var sh = el("thead");
        var shr = el("tr");
        ["Grade", "Percentage"].forEach(function (h) { shr.appendChild(el("th", null, h)); });
        sh.appendChild(shr);
        st.appendChild(sh);
        var sb = el("tbody");
        C.gradeScale.forEach(function (row) {
          var tr = el("tr");
          tr.appendChild(withLabel(el("td", null, row.grade), "Grade"));
          tr.appendChild(withLabel(el("td", "num", row.range), "Percentage"));
          sb.appendChild(tr);
        });
        st.appendChild(sb);
        gradeHost.appendChild(wrapTable(st));
        gradeHost.appendChild(el("p", "muted",
          "Final grades are rounded to the nearest whole percent. I do not curve down."));
      }
    }
  }

  // data-label drives the stacked "card" layout tables get on narrow screens.
  function withLabel(td, label) {
    td.setAttribute("data-label", label);
    return td;
  }

  function wrapTable(table) {
    var scroller = el("div", "table-scroll");
    scroller.setAttribute("tabindex", "0");
    scroller.setAttribute("role", "region");
    scroller.appendChild(table);
    return scroller;
  }

  /* ---------- schedule ---------------------------------------------------- */

  function renderSchedule() {
    var host = $("[data-schedule]");
    if (!host) return;

    var now = Number(C.currentWeek) || 0;

    (C.schedule || []).forEach(function (w) {
      var isNow = !w.break && Number(w.week) === now;
      var isPast = !w.break && now > 0 && Number(w.week) < now;

      var row = el("article", "week" +
        (w.break ? " week--break" : "") +
        (isNow ? " week--current" : "") +
        (isPast ? " week--past" : ""));

      if (isNow) row.id = "this-week";

      var head = el("header", "week__head");

      var num = el("div", "week__num");
      num.appendChild(el("span", "week__numlabel", w.break ? "Break" : "Week"));
      if (!w.break) num.appendChild(el("span", "week__numval", String(w.week)));
      head.appendChild(num);

      var titles = el("div", "week__titles");
      var h2 = el("h2", "week__topic", w.topic);
      titles.appendChild(h2);
      titles.appendChild(el("p", "week__dates", w.dates));
      if (isNow) {
        var badge = el("span", "badge badge--now", "This week");
        titles.appendChild(badge);
      }
      head.appendChild(titles);
      row.appendChild(head);

      var body = el("div", "week__body");

      if ((w.lecture || []).length) {
        body.appendChild(subhead("In class"));
        body.appendChild(bulletList(w.lecture));
      }

      if ((w.reading || []).length) {
        body.appendChild(subhead("Reading"));
        var ul = el("ul", "tight");
        w.reading.forEach(function (r) {
          var li = el("li");
          if (isBlank(r.url)) {
            li.textContent = r.text;
          } else {
            var a = el("a", null, r.text);
            a.href = r.url;
            a.rel = "noopener";
            a.target = "_blank";
            li.appendChild(a);
          }
          ul.appendChild(li);
        });
        body.appendChild(ul);
      }

      if (!isBlank(w.lab)) {
        body.appendChild(subhead("Lab"));
        body.appendChild(el("p", "tight-p", w.lab));
      }

      if (!isBlank(w.due)) {
        body.appendChild(subhead("Due"));
        var due = el("p", "pill pill--due");
        due.textContent = w.due;
        body.appendChild(due);
      }

      if (body.childNodes.length) row.appendChild(body);
      host.appendChild(row);
    });

    // Jump-to-this-week button
    var jump = $("[data-jump-week]");
    if (jump) {
      if (document.getElementById("this-week")) {
        jump.href = "#this-week";
      } else {
        jump.remove();
      }
    }
  }

  function subhead(text) {
    return el("h3", "week__subhead", text);
  }

  /* ---------- assignments -------------------------------------------------- */

  function renderAssignments() {
    var host = $("[data-assignments]");
    if (!host) return;

    (C.assignments || []).forEach(function (a) {
      var card = el("article", "assignment assignment--" + (a.status || "open"));
      card.id = a.id;

      var head = el("header", "assignment__head");
      var titleRow = el("div", "assignment__titlerow");
      titleRow.appendChild(el("h2", null, a.title));
      titleRow.appendChild(statusBadge(a.status));
      head.appendChild(titleRow);

      var meta = el("p", "assignment__meta");
      var bits = [];
      if (!isBlank(a.posted)) bits.push("Posted " + a.posted);
      if (!isBlank(a.due)) bits.push("Due " + a.due);
      if (a.points) bits.push(a.points + " points");
      meta.textContent = bits.join("  ·  ");
      head.appendChild(meta);
      card.appendChild(head);

      if (!isBlank(a.summary)) {
        card.appendChild(el("p", "assignment__summary", a.summary));
      }

      if (a.status === "upcoming") {
        card.appendChild(el("p", "note",
          "Full details, starter code, and the rubric will appear here when this assignment is posted."));
        host.appendChild(card);
        return;
      }

      if ((a.objectives || []).length) {
        card.appendChild(el("h3", null, "What this assignment is for"));
        card.appendChild(bulletList(a.objectives));
      }

      if ((a.requirements || []).length) {
        card.appendChild(el("h3", null, "Requirements"));
        card.appendChild(bulletList(a.requirements));
      }

      if (a.starter && !isBlank(a.starter.code)) {
        card.appendChild(el("h3", null, "Starter code"));
        card.appendChild(el("p", "muted",
          "Copy this into a new file called " + (a.starter.filename || "starter.py") + " and fill in the TODOs."));
        card.appendChild(codeBlock(a.starter.code, a.starter.filename));
      }

      if ((a.rubric || []).length) {
        card.appendChild(el("h3", null, "How it is graded"));
        var table = el("table", "table table--compact");
        var thead = el("thead");
        var hr = el("tr");
        ["Criterion", "Points"].forEach(function (h) { hr.appendChild(el("th", null, h)); });
        thead.appendChild(hr);
        table.appendChild(thead);
        var tbody = el("tbody");
        var sum = 0;
        a.rubric.forEach(function (r) {
          sum += Number(r.points) || 0;
          var tr = el("tr");
          tr.appendChild(withLabel(el("td", null, r.criterion), "Criterion"));
          tr.appendChild(withLabel(el("td", "num", String(r.points)), "Points"));
          tbody.appendChild(tr);
        });
        table.appendChild(tbody);
        var tfoot = el("tfoot");
        var fr = el("tr");
        fr.appendChild(el("td", null, "Total"));
        fr.appendChild(el("td", "num", String(sum)));
        tfoot.appendChild(fr);
        table.appendChild(tfoot);
        card.appendChild(wrapTable(table));

        if (a.points && sum !== Number(a.points)) {
          var warn = el("p", "warning");
          warn.textContent = "Heads up (visible to everyone): this rubric adds to " + sum +
            " but the assignment is listed as " + a.points + " points. Fix one of them in data.js.";
          card.appendChild(warn);
        }
      }

      if (!isBlank(a.submit)) {
        card.appendChild(el("h3", null, "How to submit"));
        card.appendChild(el("p", null, a.submit));
      }

      host.appendChild(card);
    });

    // Contents list at the top of the page
    var toc = $("[data-assignments-toc]");
    if (toc) {
      var ul = el("ul", "toc");
      (C.assignments || []).forEach(function (a) {
        var li = el("li");
        var link = el("a", null, a.title);
        link.href = "#" + a.id;
        li.appendChild(link);
        if (a.status === "upcoming") {
          li.appendChild(document.createTextNode(" "));
          li.appendChild(el("span", "badge badge--upcoming", "not yet posted"));
        }
        ul.appendChild(li);
      });
      toc.appendChild(ul);
    }

    renderExamples();
  }

  function statusBadge(status) {
    if (status === "upcoming") return el("span", "badge badge--upcoming", "Not yet posted");
    if (status === "closed") return el("span", "badge badge--closed", "Closed");
    return el("span", "badge badge--open", "Open");
  }

  function renderExamples() {
    var host = $("[data-examples]");
    if (!host) return;

    (C.examples || []).forEach(function (ex) {
      var block = el("section", "example");
      block.appendChild(el("h3", null, ex.title));
      if (!isBlank(ex.description)) {
        block.appendChild(html(el("p", "prose"), ex.description));
      }
      block.appendChild(codeBlock(ex.code, ex.filename || "Python"));
      host.appendChild(block);
    });
  }

  /* ---------- mobile navigation ------------------------------------------ */

  function initNav() {
    var toggle = $(".nav__toggle");
    var list = $("#nav-list");
    if (!toggle || !list) return;

    // The menu is only collapsible when JS is available; reveal the button now.
    toggle.hidden = false;
    document.body.classList.add("js-nav");

    toggle.addEventListener("click", function () {
      var open = toggle.getAttribute("aria-expanded") === "true";
      toggle.setAttribute("aria-expanded", String(!open));
      list.classList.toggle("is-open", !open);
    });

    // Close after tapping a link (matters for same-page anchors).
    list.addEventListener("click", function (e) {
      if (e.target.tagName === "A" && list.classList.contains("is-open")) {
        list.classList.remove("is-open");
        toggle.setAttribute("aria-expanded", "false");
      }
    });

    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && list.classList.contains("is-open")) {
        list.classList.remove("is-open");
        toggle.setAttribute("aria-expanded", "false");
        toggle.focus();
      }
    });
  }

  /* ---------- boot --------------------------------------------------------- */

  function boot() {
    if (!C) {
      showFatal("data.js did not load. Check that js/data.js exists and that the " +
                "<script> tag for it appears before app.js.");
      return;
    }
    try {
      renderChrome();
      initNav();
      renderHome();
      renderSyllabus();
      renderSchedule();
      renderAssignments();
      renderContact();
    } catch (err) {
      showFatal("Something in data.js is malformed, so part of this page could not be " +
                "built. Technical detail: " + err.message);
      throw err;
    }
  }

  function showFatal(message) {
    var bar = el("div", "fatal");
    bar.setAttribute("role", "alert");
    bar.textContent = message;
    if (document.body.firstChild) {
      document.body.insertBefore(bar, document.body.firstChild);
    } else {
      document.body.appendChild(bar);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();

[Write file: style.css]
/* ==========================================================================
   CS 101 course site — stylesheet
   Mobile-first. Everything below 720px is the default; wider screens are
   handled by the media queries near the bottom.
   To recolor the whole site, change the variables in :root.
   ========================================================================== */

:root {
  --ink:        #14181f;
  --ink-soft:   #4a5462;
  --ink-faint:  #6b7482;
  --paper:      #ffffff;
  --paper-alt:  #f5f7fa;
  --line:       #dfe4ea;
  --line-soft:  #eceff3;

  --accent:      #1f5fa8;
  --accent-dark: #17497f;
  --accent-wash: #eaf2fb;

  --good:      #1c6b45;
  --good-wash: #e6f4ec;
  --warn:      #8a5a00;
  --warn-wash: #fdf3e0;
  --stop:      #9b2226;
  --stop-wash: #fbeaea;

  --code-bg:   #1c2128;
  --code-ink:  #e6edf3;
  --code-bar:  #262d36;

  --radius: 10px;
  --shadow: 0 1px 2px rgba(20, 24, 31, .06), 0 4px 14px rgba(20, 24, 31, .05);

  --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;

  --wrap: 62rem;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ink:        #e8ecf2;
    --ink-soft:   #aab4c2;
    --ink-faint:  #8d97a5;
    --paper:      #12151a;
    --paper-alt:  #191d24;
    --line:       #2b323c;
    --line-soft:  #232932;

    --accent:      #7fb2ec;
    --accent-dark: #a8cbf5;
    --accent-wash: #16243a;

    --good:      #6fce9f;
    --good-wash: #12281d;
    --warn:      #e2b666;
    --warn-wash: #2b2314;
    --stop:      #f0908f;
    --stop-wash: #2e1618;

    --code-bg:   #0c0f14;
    --code-bar:  #171c23;

    --shadow: 0 1px 2px rgba(0, 0, 0, .4), 0 4px 14px rgba(0, 0, 0, .3);
  }
}

/* ---------- reset-ish ---------------------------------------------------- */

*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;   /* stop iOS enlarging text in landscape */
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  * { animation-duration: .001ms !important; transition-duration: .001ms !important; }
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 1.0625rem;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; }

a { color: var(--accent); text-underline-offset: 2px; }
a:hover { color: var(--accent-dark); }

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-radius: 3px;
}

h1, h2, h3 { line-height: 1.25; text-wrap: balance; }
h1 { font-size: clamp(1.75rem, 5vw, 2.5rem); margin: 0 0 .4em; letter-spacing: -.015em; }
h2 { font-size: clamp(1.3rem, 3.4vw, 1.6rem); margin: 2rem 0 .6rem; letter-spacing: -.01em; }
h3 { font-size: 1.08rem; margin: 1.5rem 0 .4rem; }

p { margin: 0 0 1rem; }
ul, ol { margin: 0 0 1rem; padding-left: 1.3rem; }
li { margin: .25rem 0; }
li > ul { margin-top: .25rem; }

.sr-only {
  position: absolute; width: 1px; height: 1px;
  margin: -1px; padding: 0; overflow: hidden;
  clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap;
}

.skip-link {
  position: absolute; left: -9999px; top: 0; z-index: 100;
  background: var(--accent); color: #fff;
  padding: .7rem 1.1rem; border-radius: 0 0 var(--radius) 0;
  font-weight: 600; text-decoration: none;
}
.skip-link:focus { left: 0; color: #fff; }

/* ---------- layout -------------------------------------------------------- */

.wrap {
  width: 100%;
  max-width: var(--wrap);
  margin-inline: auto;
  padding-inline: 1.1rem;
}

main { padding-block: 1.5rem 3rem; }

.section { margin-block: 2.25rem; scroll-margin-top: 5rem; }
.section > h2:first-child { margin-top: 0; }

.prose > :last-child { margin-bottom: 0; }

/* ---------- header + nav --------------------------------------------------- */

.masthead {
  background: var(--paper-alt);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 20;
}

.masthead__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 3.5rem;
  padding-block: .5rem;
}

.brand {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
  line-height: 1.2;
}
.brand__code { font-weight: 700; font-size: 1.05rem; letter-spacing: .01em; }
.brand__term { font-size: .78rem; color: var(--ink-faint); }

.nav__toggle {
  font: inherit;
  font-size: .9rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: .45rem;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: .55rem .8rem;
  min-height: 44px;              /* comfortable tap target */
  cursor: pointer;
}
.nav__toggle:hover { border-color: var(--accent); }
.nav__bars { display: block; width: 1.05rem; height: 2px; background: currentColor;
             position: relative; }
.nav__bars::before, .nav__bars::after {
  content: ""; position: absolute; left: 0; width: 100%; height: 2px; background: currentColor;
}
.nav__bars::before { top: -5px; }
.nav__bars::after  { top: 5px; }

.nav__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: .15rem .35rem;
}

.nav a {
  display: block;
  padding: .55rem .7rem;
  border-radius: var(--radius);
  text-decoration: none;
  color: var(--ink-soft);
  font-weight: 600;
  font-size: .94rem;
}
.nav a:hover { background: var(--accent-wash); color: var(--accent-dark); }
.nav a.is-current { color: var(--accent-dark); background: var(--accent-wash); }

/* Small screens, JS available: collapse the list behind the button. */
@media (max-width: 719px) {
  .js-nav .nav__list {
    display: none;
    position: absolute;
    left: 0; right: 0;
    top: 100%;
    flex-direction: column;
    gap: 0;
    background: var(--paper);
    border-bottom: 1px solid var(--line);
    box-shadow: var(--shadow);
    padding: .4rem .8rem .8rem;
  }
  .js-nav .nav__list.is-open { display: flex; }
  .js-nav .nav a { padding: .8rem .6rem; border-radius: 8px; }
  .masthead__inner { position: relative; }
  /* No JS: the list just wraps under the brand, which is fine. */
}

/* ---------- hero ------------------------------------------------------------ */

.hero {
  background: linear-gradient(180deg, var(--accent-wash), var(--paper));
  border-bottom: 1px solid var(--line);
  padding-block: 2.25rem 2rem;
}
.hero h1 { margin-bottom: .3rem; }
.hero__tagline {
  font-size: 1.1rem;
  color: var(--ink-soft);
  max-width: 46ch;
  margin-bottom: 1.1rem;
}
.hero__meta {
  font-size: .95rem;
  color: var(--ink-faint);
  margin-bottom: 1.2rem;
}

.btnrow { display: flex; flex-wrap: wrap; gap: .6rem; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: .6rem 1.05rem;
  border-radius: var(--radius);
  background: var(--paper);
  border: 1px solid var(--line);
  color: var(--ink);
  font-weight: 600;
  font-size: .95rem;
  text-decoration: none;
}
.btn:hover { border-color: var(--accent); color: var(--accent-dark); }
.btn--primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}
.btn--primary:hover { background: var(--accent-dark); border-color: var(--accent-dark); color: #fff; }

@media (prefers-color-scheme: dark) {
  .btn--primary { color: #0d1117; }
  .btn--primary:hover { color: #0d1117; }
}

.link { font-weight: 600; }

/* ---------- panels, cards ---------------------------------------------------- */

.panel {
  background: var(--paper-alt);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.15rem 1.15rem 1.25rem;
  margin-block: 1.25rem;
}
.panel > :first-child { margin-top: 0; }
.panel > :last-child { margin-bottom: 0; }

.panel--accent {
  background: var(--accent-wash);
  border-color: color-mix(in srgb, var(--accent) 30%, transparent);
}

.cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-block: 1.25rem;
}

.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.05rem 1.1rem;
  box-shadow: var(--shadow);
}
.card > :first-child { margin-top: 0; }
.card > :last-child { margin-bottom: 0; }
.card--wide { grid-column: 1 / -1; margin-block: 1rem 0; }

.muted { color: var(--ink-faint); font-size: .92rem; }
.note {
  font-size: .92rem;
  color: var(--ink-soft);
  background: var(--paper-alt);
  border-left: 3px solid var(--line);
  padding: .6rem .8rem;
  border-radius: 0 6px 6px 0;
  margin-block: .9rem;
}
.warning {
  font-size: .92rem;
  color: var(--warn);
  background: var(--warn-wash);
  border: 1px solid color-mix(in srgb, var(--warn) 35%, transparent);
  border-radius: 8px;
  padding: .65rem .85rem;
  margin-block: .9rem;
}
.fatal {
  background: var(--stop-wash);
  color: var(--stop);
  border-bottom: 2px solid var(--stop);
  padding: .9rem 1.1rem;
  font-size: .95rem;
  font-weight: 600;
}

.tight { margin-bottom: .6rem; }
.tight-p { margin-bottom: .6rem; }

/* ---------- definition lists -------------------------------------------------- */

.kv { margin: .6rem 0 0; }
.kv dt {
  font-size: .74rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--ink-faint);
  font-weight: 700;
  margin-top: .7rem;
}
.kv dd { margin: .1rem 0 0; }

@media (min-width: 30rem) {
  .kv--split {
    display: grid;
    grid-template-columns: minmax(7rem, 11rem) 1fr;
    column-gap: 1.1rem;
    row-gap: .1rem;
    align-items: baseline;
  }
  .kv--split dt { margin-top: .55rem; }
  .kv--split dd { margin-top: .55rem; }
}

/* ---------- table of contents --------------------------------------------------- */

.toc { list-style: none; padding: 0; margin: .4rem 0 0; }
.toc li { margin: 0; border-bottom: 1px solid var(--line-soft); }
.toc li:last-child { border-bottom: 0; }
.toc a {
  display: block;
  padding: .65rem .1rem;
  text-decoration: none;
  font-weight: 600;
  font-size: .95rem;
}
.toc a:hover { text-decoration: underline; }

/* ---------- announcements -------------------------------------------------------- */

.announcement {
  border-left: 3px solid var(--accent);
  padding: .1rem 0 .1rem 1rem;
  margin-block: 1.4rem;
}
.announcement h3 { margin: .1rem 0 .35rem; }
.announcement__date {
  font-size: .78rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--ink-faint);
  font-weight: 700;
  margin: 0;
}

.pill {
  display: inline-block;
  font-size: .88rem;
  font-weight: 600;
  padding: .4rem .7rem;
  border-radius: 999px;
  margin-block: .5rem;
}
.pill--due { background: var(--warn-wash); color: var(--warn); }

.badge {
  display: inline-block;
  font-size: .72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .05em;
  padding: .22rem .55rem;
  border-radius: 999px;
  white-space: nowrap;
  vertical-align: middle;
}
.badge--now      { background: var(--good-wash); color: var(--good); }
.badge--open     { background: var(--good-wash); color: var(--good); }
.badge--upcoming { background: var(--paper-alt); color: var(--ink-faint); border: 1px solid var(--line); }
.badge--closed   { background: var(--stop-wash); color: var(--stop); }

/* ---------- schedule ---------------------------------------------------------------- */

.week {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1rem 1.05rem 1.1rem;
  margin-block: .9rem;
  background: var(--paper);
  scroll-margin-top: 5rem;
}
.week--current {
  border-color: var(--accent);
  border-width: 2px;
  background: var(--accent-wash);
  box-shadow: var(--shadow);
}
.week--past { opacity: .72; }
.week--past:hover { opacity: 1; }
.week--break {
  background: var(--paper-alt);
  border-style: dashed;
  text-align: center;
}
.week--break .week__head { justify-content: center; }

.week__head {
  display: flex;
  align-items: baseline;
  gap: .9rem;
}
.week__num {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 0 0 auto;
  min-width: 2.6rem;
  line-height: 1.1;
}
.week__numlabel {
  font-size: .64rem;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--ink-faint);
  font-weight: 700;
}
.week__numval { font-size: 1.5rem; font-weight: 700; }
.week__titles { flex: 1 1 auto; min-width: 0; }
.week__topic { font-size: 1.12rem; margin: 0 0 .1rem; }
.week__dates { font-size: .85rem; color: var(--ink-faint); margin: 0 0 .25rem; }

.week__body { margin-top: .85rem; }
.week__subhead {
  font-size: .72rem;
  text-transform: uppercase;
  letter-spacing: .07em;
  color: var(--ink-faint);
  font-weight: 700;
  margin: 1rem 0 .3rem;
}
.week__body > .week__subhead:first-child { margin-top: 0; }

/* ---------- tables --------------------------------------------------------------------- */

.table-scroll { margin-block: 1rem; }

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: .95rem;
}
.table th {
  text-align: left;
  font-size: .74rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--ink-faint);
  border-bottom: 2px solid var(--line);
  padding: .5rem .6rem;
}
.table td {
  padding: .6rem;
  border-bottom: 1px solid var(--line-soft);
  vertical-align: top;
}
.table tfoot td {
  font-weight: 700;
  border-top: 2px solid var(--line);
  border-bottom: 0;
}
.table .num { white-space: nowrap; font-variant-numeric: tabular-nums; }

/* Narrow screens: turn each row into a stacked card. The data-label attribute
   set in app.js supplies the header text for each cell. */
@media (max-width: 39.99rem) {
  .table, .table thead, .table tbody, .table tfoot, .table tr, .table th, .table td {
    display: block;
  }
  .table thead { display: none; }
  .table tr {
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: .5rem .7rem;
    margin-bottom: .6rem;
  }
  .table td {
    border: 0;
    padding: .3rem 0;
    display: flex;
    justify-content: space-between;
    gap: 1rem;
  }
  .table td::before {
    content: attr(data-label);
    font-size: .72rem;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: var(--ink-faint);
    font-weight: 700;
    flex: 0 0 auto;
    padding-top: .15rem;
  }
  .table td:not([data-label])::before { content: none; }
  .table td .num, .table .num { text-align: right; }
  .table tfoot tr { border-color: var(--ink-faint); }
}

@media (min-width: 40rem) {
  .table-scroll { overflow-x: auto; }
}

/* ---------- assignments ------------------------------------------------------------------ */

.assignment {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.15rem 1.15rem 1.3rem;
  margin-block: 1.6rem;
  background: var(--paper);
  scroll-margin-top: 5rem;
}
.assignment--upcoming { background: var(--paper-alt); }
.assignment__head { border-bottom: 1px solid var(--line-soft); padding-bottom: .8rem; }
.assignment__titlerow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .6rem;
}
.assignment__titlerow h2 { margin: 0; font-size: 1.2rem; }
.assignment__meta {
  margin: .5rem 0 0;
  font-size: .88rem;
  color: var(--ink-faint);
  font-weight: 600;
}
.assignment__summary { margin-top: 1rem; }
.assignment h3 { font-size: .95rem; }

.example { margin-block: 2rem; }
.example h3 { font-size: 1.08rem; }

/* ---------- code blocks --------------------------------------------------------------------- */

.codeblock {
  margin-block: 1rem;
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--code-bg);
}

.codeblock__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .6rem;
  background: var(--code-bar);
  padding: .4rem .5rem .4rem .85rem;
  border-bottom: 1px solid rgba(255, 255, 255, .08);
}
.codeblock__name {
  font-family: var(--mono);
  font-size: .78rem;
  color: #9aa7b6;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.copybtn {
  font: inherit;
  font-size: .8rem;
  font-weight: 600;
  color: #d7e0ea;
  background: rgba(255, 255, 255, .08);
  border: 1px solid rgba(255, 255, 255, .16);
  border-radius: 7px;
  padding: .35rem .7rem;
  min-height: 34px;
  min-width: 5.2rem;
  cursor: pointer;
  flex: 0 0 auto;
}
.copybtn:hover { background: rgba(255, 255, 255, .16); }
.copybtn.is-copied {
  background: rgba(111, 206, 159, .2);
  border-color: rgba(111, 206, 159, .5);
  color: #b6ecd0;
}
.copybtn.is-failed {
  background: rgba(240, 144, 143, .2);
  border-color: rgba(240, 144, 143, .5);
  color: #f5c3c2;
}
.copybtn:focus-visible { outline-color: #9ec5f0; }

.codeblock__pre {
  margin: 0;
  padding: .9rem 1rem 1.1rem;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  background: var(--code-bg);
}
.codeblock__pre code {
  font-family: var(--mono);
  font-size: .84rem;
  line-height: 1.6;
  color: var(--code-ink);
  white-space: pre;
  tab-size: 4;
}

/* Inline code inside prose */
:not(pre) > code {
  font-family: var(--mono);
  font-size: .88em;
  background: var(--paper-alt);
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: .1em .35em;
  overflow-wrap: break-word;
}

/* ---------- footer ------------------------------------------------------------------------------ */

.footer {
  border-top: 1px solid var(--line);
  background: var(--paper-alt);
  padding-block: 1.75rem 2.25rem;
  margin-top: 3rem;
  font-size: .9rem;
  color: var(--ink-faint);
}
.footer a { color: var(--accent); }
.footer p { margin-bottom: .5rem; }
.footer__links {
  list-style: none;
  padding: 0;
  margin: 0 0 1rem;
  display: flex;
  flex-wrap: wrap;
  gap: .3rem 1.1rem;
}
.footer__links a { font-weight: 600; text-decoration: none; }
.footer__links a:hover { text-decoration: underline; }

/* ---------- wider screens --------------------------------------------------------------------------- */

@media (min-width: 45rem) {
  .cards { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 720px) {
  .nav__toggle { display: none !important; }
  .nav__list { display: flex !important; }
}

@media (min-width: 60rem) {
  body { font-size: 1.09375rem; }
  .split {
    display: grid;
    grid-template-columns: 1fr 20rem;
    gap: 2.5rem;
    align-items: start;
  }
  .split__aside { position: sticky; top: 4.75rem; }
}

/* ---------- print ------------------------------------------------------------------------------------- */

@media print {
  .masthead, .footer, .copybtn, .skip-link, .btnrow, .toc { display: none !important; }
  body { font-size: 11pt; color: #000; background: #fff; }
  .hero { background: none; border: 0; padding-block: 0 1rem; }
  .week, .assignment, .card, .panel { break-inside: avoid; border-color: #999; }
  .codeblock { border-color: #999; }
  .codeblock__bar { background: #eee; }
  .codeblock__name { color: #333; }
  .codeblock__pre, .codeblock { background: #f6f6f6; }
  .codeblock__pre code { color: #000; white-space: pre-wrap; }
  a[href^="http"]::after { content: " (" attr(href) ")"; font-size: 9pt; color: #555; }
  .table-scroll { overflow: visible; }
}

