31	  // "2027-01-19" -> "January 19, 2027". Anything else is passed through as-is.
32	  function prettyDate(iso) {
33	    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || "").trim());
34	    if (!m) return iso || "";
35	    var months = ["January", "February", "March", "April", "May", "June", "July",
36	                  "August", "September", "October", "November", "December"];
37	    return months[Number(m[2]) - 1] + " " + Number(m[3]) + ", " + m[1];
38	  }
