443	  // data-label drives the stacked "card" layout tables get on narrow screens.
444	  function withLabel(td, label) {
445	    td.setAttribute("data-label", label);
446	    return td;
447	  }
448	
449	  // Wrap a table so it can scroll sideways on small screens. A scrollable region
450	  // must be keyboard-reachable and needs an accessible name to go with role=region.
451	  function wrapTable(table, label) {
452	    var scroller = el("div", "table-scroll");
453	    scroller.setAttribute("tabindex", "0");
454	    scroller.setAttribute("role", "region");
455	    scroller.setAttribute("aria-label", label || "Table");
456	    scroller.appendChild(table);
457	    return scroller;
458	  }
