691	  /* ---------- mobile navigation ------------------------------------------ */
692	
693	  function initNav() {
694	    var toggle = $(".nav__toggle");
695	    var list = $("#nav-list");
696	    if (!toggle || !list) return;
697	
698	    // The menu is only collapsible when JS is available; reveal the button now.
699	    toggle.hidden = false;
700	    document.body.classList.add("js-nav");
701	
702	    toggle.addEventListener("click", function () {
703	      var open = toggle.getAttribute("aria-expanded") === "true";
704	      toggle.setAttribute("aria-expanded", String(!open));
705	      list.classList.toggle("is-open", !open);
706	    });
707	
708	    // Close after tapping a link (matters for same-page anchors).
709	    list.addEventListener("click", function (e) {
710	      if (e.target.tagName === "A" && list.classList.contains("is-open")) {
711	        list.classList.remove("is-open");
712	        toggle.setAttribute("aria-expanded", "false");
713	      }
714	    });
715	
716	    document.addEventListener("keydown", function (e) {
717	      if (e.key === "Escape" && list.classList.contains("is-open")) {
718	        list.classList.remove("is-open");
719	        toggle.setAttribute("aria-expanded", "false");
720	        toggle.focus();
721	      }
722	    });
723	  }
