728	    if (!C) {
729	      showFatal("data.js did not load. Check that js/data.js exists and that the " +
730	                "<script> tag for it appears before app.js.");
731	      return;
732	    }
733	    try {
734	      renderChrome();
735	      initNav();
736	      renderHome();
737	      renderSyllabus();
738	      renderSchedule();
739	      renderAssignments();
740	      renderExamples();
741	      renderContact();
742	    } catch (err) {
743	      showFatal("Something in data.js is malformed, so part of this page could not be " +
744	                "built. Technical detail: " + err.message);
745	      throw err;
746	    }
747	  }
748	
749	  function showFatal(message) {
750	    var bar = el("div", "fatal");
751	    bar.setAttribute("role", "alert");
752	    bar.textContent = message;
753	    if (document.body.firstChild) {
754	      document.body.insertBefore(bar, document.body.firstChild);
755	    } else {
756	      document.body.appendChild(bar);
757	    }
758	  }
759	
760	  if (document.readyState === "loading") {
761	    document.addEventListener("DOMContentLoaded", boot);
762	  } else {
763	    boot();
764	  }
