670	  /* ---------- labs ----------------------------------------------------------
671	     Built from the same `schedule` data as the schedule page, so the two can
672	     never disagree. A lab counts as graded when its text starts with "Lab <n>";
673	     anything else (a project work session, drop-in help) is listed but not
674	     counted.                                                                  */
675	
676	  function renderLabs() {
677	    var host = $("[data-labs]");
678	    if (!host) return;
679	
680	    var rows = (C.schedule || []).filter(function (w) {
681	      return !w.break && !isBlank(w.lab);
682	    });
683	
684	    var section = host.parentNode;
685	    if (!rows.length) {
686	      if (section && section.tagName === "SECTION") section.remove();
687	      return;
688	    }
689	
690	    var graded = rows.filter(function (w) { return /^Lab\s+\d+/.test(w.lab); });
691	
692	    var intro = el("p");
693	    intro.textContent = "Lab meets every week of the term. There are " +
694	      graded.length + " graded labs; the remaining sessions are open work time. " +
695	      "Labs are completion-graded — show up, do the work, submit before you leave.";
696	    host.appendChild(intro);
697	
698	    var table = el("table", "table");
699	    var thead = el("thead");
700	    var hr = el("tr");
701	    ["Week", "Dates", "Lab"].forEach(function (h) { hr.appendChild(el("th", null, h)); });
702	    thead.appendChild(hr);
703	    table.appendChild(thead);
704	
705	    var tbody = el("tbody");
706	    rows.forEach(function (w) {
707	      var tr = el("tr");
708	      tr.appendChild(withLabel(el("td", "num", String(w.week)), "Week"));
709	      tr.appendChild(withLabel(el("td", "muted", w.dates), "Dates"));
710	      tr.appendChild(withLabel(el("td", null, w.lab), "Lab"));
711	      tbody.appendChild(tr);
712	    });
713	    table.appendChild(tbody);
714	
715	    host.appendChild(wrapTable(table, "Lab schedule"));
716	
717	    var note = el("p", "note");
718	    note.appendChild(document.createTextNode(
719	      "Lab handouts are given out in the session itself. Your lowest few lab scores " +
720	      "are dropped automatically — see "));
